-- Desktops 1-4 live on the main monitor. Desktop 5 is the TV, and exists only while the TV output
-- is on: Opt+5 / Opt+Shift+5 do nothing without it, Opt+P/N skip it, and turning it off (or
-- unplugging) moves its windows to the desktop you're on. The bar (quickshell/Workspaces.qml)
-- shows V only while the TV is on.
-- The TV reports "connected" even when switched off with its remote, so Hyprland can't tell by
-- itself: the output starts off at login and the control center's TV switch calls D.set_tv().
-- Used by binds.lua (generated by keys/build.py): D.go(n), D.move(n), D.step(d), D.move_step(d).
local M = {}

M.main = "Samsung Electric Company LS27FG53x"   -- description prefixes, as in `hyprctl monitors`
M.tv   = "Sony SONY TV"
M.tv_desktop = 5

local function find(prefix)   -- enabled monitors only
    for _, m in ipairs(hl.get_monitors()) do
        if m.enabled ~= false and m.description:sub(1, #prefix) == prefix then return m end
    end
end

function M.count()
    return find(M.tv) and M.tv_desktop or M.tv_desktop - 1
end

local function active_id()
    return (hl.get_active_workspace() or {}).id or 1
end

function M.go(n)
    if n <= M.count() then hl.dispatch(hl.dsp.focus({ workspace = n })) end
end

-- Moving a window doesn't switch desktop (like KDE's "Window to Desktop N").
function M.move(n)
    if n <= M.count() then hl.dispatch(hl.dsp.window.move({ workspace = n, follow = false })) end
end

local function stepped(d)
    local n, id = M.count(), active_id()
    if id > n then id = 1 end
    return (id - 1 + d) % n + 1
end
function M.step(d) M.go(stepped(d)) end
function M.move_step(d) M.move(stepped(d)) end

-- TV output on/off. Live monitor rules can't reliably turn a disabled output back on (they
-- pile up), so the state goes in a file and the config is reloaded, which rebuilds the rules.
-- `hyprctl eval 'require("desktops").set_tv(true)'` (the control center's TV switch does this)
local state_file = (os.getenv("XDG_RUNTIME_DIR") or "/tmp") .. "/hypr-tv"

local function read_state()
    local f = io.open(state_file)
    if not f then return false end
    local on = f:read("l") == "on"
    f:close()
    return on
end

function M.set_tv(on)
    local f = io.open(state_file, "w")
    f:write(on and "on" or "off")
    f:close()
    hl.dispatch(hl.dsp.exec_cmd("hyprctl reload"))
end

-- No monitors yet = Hyprland is starting (login): the TV starts off.
if #hl.get_monitors() == 0 then
    local f = io.open(state_file, "w")
    f:write("off")
    f:close()
end
if not read_state() then
    hl.monitor({ output = "desc:" .. M.tv, disabled = true })
end

-- each desktop opens on its monitor; the TV starts on desktop 5
for i = 1, M.tv_desktop - 1 do
    hl.workspace_rule({ workspace = tostring(i), monitor = "desc:" .. M.main })
end
hl.workspace_rule({ workspace = tostring(M.tv_desktop), monitor = "desc:" .. M.tv, default = true })

-- TV turned off or unplugged: bring its windows to the desktop you're on
hl.on("monitor.removed", function()
    if find(M.tv) then return end
    local here = active_id()
    if here == M.tv_desktop then return end
    for _, w in ipairs(hl.get_windows({ workspace = tostring(M.tv_desktop) })) do
        hl.dispatch(hl.dsp.window.move({ workspace = here, window = "address:" .. w.address, follow = false }))
    end
end)

return M
